import { NgClass, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  OnDestroy,
  OnInit,
  Output,
  TemplateRef,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { accordionAnimations } from '@questrade/allspark-angular-components/core/animations';
import { QExpansionTriggerComponent } from '@questrade/allspark-angular-components/core/components';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { chevronDown } from '@questrade/allspark-icons/icons';
import { QAccordionComponent } from './accordion.component';

@Component({
  imports: [QExpansionTriggerComponent, NgIf, NgClass, NgTemplateOutlet],
  selector: 'q-accordion-panel',
  templateUrl: './accordion-panel.component.html',
  styleUrls: ['./accordion-panel.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  animations: [accordionAnimations.bodyExpansion],
})
export class QAccordionPanelComponent implements OnInit, OnDestroy {
  @Output() readonly activeChange = new EventEmitter<boolean>();

  @Input() title = '';
  @Input() subTitle = '';
  @Input({ transform: booleanAttribute }) active = false;
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input({ transform: booleanAttribute }) showIcon = true;
  @Input() headerAdditionalContentTemplate: TemplateRef<unknown> | null = null;
  @Input() headerAdditionalContentContext: unknown | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-accordion-panel';

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-accordion-panel',
      this.active && 'q-accordion-panel-active',
      this.disabled && 'q-accordion-panel-disabled',
    ]
      .filter(Boolean)
      .join(' ');
  }

  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _accordionComponent = inject(QAccordionComponent, { host: true });

  ngOnInit(): void {
    this._iconRegistry.registerIcon(chevronDown);
    this._accordionComponent._addPanel(this);
  }

  ngOnDestroy(): void {
    this._accordionComponent._removePanel(this);
  }

  _onHeaderClick(): void {
    if (!this.disabled) {
      this._accordionComponent._click(this);
    }
  }

  _markForCheck(): void {
    this._cdr.markForCheck();
  }
}
