import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
  booleanAttribute,
} from '@angular/core';
import { QAccordionPanelComponent } from './accordion-panel.component';
import { QAccordionHeaderSize } from './types/accordion-header-size.type';
import { QAccordionIconPosition } from './types/accordion-icon-position.type';
import { QAccordionVariant } from './types/accordion-variant.type';

@Component({
  selector: 'q-accordion',
  template: '<ng-content />',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  styleUrl: './accordion.component.scss',
})
export class QAccordionComponent {
  @Input({ transform: booleanAttribute }) singleOpen = false;
  @Input({ transform: booleanAttribute }) inset = false;
  /**
   * @deprecated There's no replacement for this input. If you need the trigger icon to be on the left
   * side, please contact the Allspark design system team.
   * @breaking-change First major after Jul 12, 2026
   */
  @Input() iconPosition: QAccordionIconPosition = 'right';
  @Input() headerSize: QAccordionHeaderSize = 'small';
  @Input() variant: QAccordionVariant = 'primary';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-accordion';

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-accordion',
      `q-accordion-header-icon-${this.iconPosition}`,
      `q-accordion-header-size-${this.headerSize}`,
      `q-accordion-variant-${this.variant}`,
      this.inset && 'q-accordion-inset',
    ]
      .filter(Boolean)
      .join(' ');
  }

  private _accordionPanels: QAccordionPanelComponent[] = [];

  _addPanel(collapsePanel: QAccordionPanelComponent): void {
    this._accordionPanels.push(collapsePanel);
  }

  _removePanel(collapsePanel: QAccordionPanelComponent): void {
    this._accordionPanels.splice(this._accordionPanels.indexOf(collapsePanel), 1);
  }

  _click(clickedPanel: QAccordionPanelComponent): void {
    if (this.singleOpen && !clickedPanel.active) {
      this._accordionPanels
        .filter((panel: QAccordionPanelComponent) => panel !== clickedPanel)
        .forEach((panel: QAccordionPanelComponent) => {
          if (panel.active) {
            panel.active = false;
            panel.activeChange.emit(panel.active);
            panel._markForCheck();
          }
        });
    }

    clickedPanel.active = !clickedPanel.active;
    clickedPanel.activeChange.emit(clickedPanel.active);
  }
}
